 "content": "from collections import Counter


def transform(grid):
    """Fill the gaps between aligned marker cells with color 3."""
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    markers = {value for value in counts if value != background}

    height = len(grid)
    width = len(grid[0]) if height else 0
    for r in range(height):
        positions = [c for c in range(width) if grid[r][c] in markers]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(width):
        positions = [r for r in range(height) if grid[r][c] in markers]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out


if __name__ == "__main__":
